            builder.Append('|');
            builder.Append("OrigClListID=");
            builder.Append('\'').Append(GetOrigClListID()).Append('\'');
            builder.Append('|');
            builder.Append("Symbol=");
            builder.Append('\'').Append(GetSymbol()).Append('\'');
            builder.Append('|');
            builder.Append("ErrorText=");
            builder.Append('\'').Append(GetErrorText()).Append('\'');

            this.Limit = originalLimit;

        }
    }
}
